/// <summary>
/// Concrete class for calculating MDF based on Delivery Fee
/// </summary>
public class METCustomerMDFCalculationRecord_DeliveryFee extends METCustomerMDFCalculationRecord
{
}

Method.Source:
/// <summary>
/// Override to calculate delivery fee based on WMSOrderTrans
/// </summary>
/// <param name = "_wMSOrderTrans">WMSOrderTrans</param>
/// <returns>Amount</returns>
Amount calcDeliveryFee(WMSOrderTrans _wMSOrderTrans)
{
    METComponentCode componentCode;
    METSalesLinePriceComponent priceComponent;

    select sum(Value) from priceComponent
        exists join componentCode
        where priceComponent.InventTransId == _wMSOrderTrans.inventTransId
           && priceComponent.Component == componentCode.Component
           && componentCode.IncludeMDFCalculation == NoYes::Yes;

    return priceComponent.Value * _wMSOrderTrans.qty;
}

